static String cacheKey(String url) {
    URI uri = URI.create(url);
    String query = uri.getQuery() == null ? "" : Arrays.stream(uri.getQuery().split("&"))
            .filter(param -> !param.startsWith("utm_"))
            .sorted()
            .collect(Collectors.joining("&"));
    return uri.getHost().toLowerCase() + uri.getPath() + (query.isEmpty() ? "" : "?" + query);
}

public static void main(String[] args) {
    Set<String> keys = new LinkedHashSet<>();
    keys.add(cacheKey("https://shop.example.com/products?page=2&sort=price"));
    keys.add(cacheKey("https://SHOP.example.com/products?sort=price&page=2&utm_source=zalo"));
    keys.add(cacheKey("https://shop.example.com/products?sort=price&page=2&utm_campaign=sale"));
    keys.add(cacheKey("https://shop.example.com/Products?page=2&sort=price"));
    System.out.println(keys.size());
}
